import {trace,layout,lanePath,minBoardWidth} from './whozzie.js?v=20261010-member-fixes';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const colours=['#4976b7','#d89445','#7b9a77','#aa79a9','#ca7475','#648c9d','#a79853','#818ac0','#cc925e','#6aab99','#a6816a','#a1718b'];
export function ladderRoundView(round,width=850){
  const boardWidth=Math.max(minBoardWidth(round.ladder.columns),Math.min(width,1400)),geometry=layout(boardWidth,round.ladder);
  const lanes=round.seats.map((player,column)=>({...trace(round.ladder,column),player}));
  const html=`<div class="ladder-paper-scroll"><svg class="ladder-paper" viewBox="0 0 ${boardWidth} ${geometry.height}" width="${boardWidth}" height="${geometry.height}" role="img" aria-label="참여자가 차례대로 진행하는 사다리"><g>${lanes.map((lane,column)=>`<line class="room-ladder-line" x1="${geometry.x(column)}" y1="${geometry.lineTop(column)}" x2="${geometry.x(column)}" y2="${geometry.flapTop(column)}"/><rect data-name-column="${column}" class="ladder-name-chip" style="stroke:${colours[lane.player]}" x="${geometry.x(column)-Math.min(geometry.labelWidth,160)/2}" y="${geometry.chipTop(column)}" width="${Math.min(geometry.labelWidth,160)}" height="40" rx="8"/><text class="ladder-name" x="${geometry.x(column)}" y="${geometry.chipTop(column)+25}" text-anchor="middle">${column+1}. ${esc(round.players[lane.player].name.slice(0,12))}</text><rect data-slot-chip="${column}" class="ladder-result-chip" x="${geometry.x(column)-geometry.flapWidth/2}" y="${geometry.flapTop(column)}" width="${geometry.flapWidth}" height="44" rx="7"/><text data-slot="${column}" class="ladder-outcome" x="${geometry.x(column)}" y="${geometry.flapTop(column)+28}" text-anchor="middle">?</text>`).join('')}${round.ladder.rungs.map((row,r)=>row.map((rung,gap)=>rung?`<line class="room-ladder-line" x1="${geometry.x(gap)}" y1="${geometry.rungY(r,gap)}" x2="${geometry.x(gap+1)}" y2="${geometry.rungY(r,gap)}"/>`:'').join('')).join('')}</g>${lanes.map((lane,column)=>{const path=lanePath(lane,geometry);return `<path data-ladder-path="${column}" class="room-ladder-route" stroke="${colours[lane.player]}" d="${path.d}" pathLength="1" stroke-dasharray="1" stroke-dashoffset="1"/><g data-ladder-ball="${column}" class="ladder-ball" style="opacity:0"><circle r="11" fill="#fff" stroke="${colours[lane.player]}" stroke-width="2.5"/><path d="M-6 -8 Q1 0 -6 8 M6 -8 Q-1 0 6 8" fill="none" stroke="#c97671" stroke-width="1.5"/></g>`;}).join('')}</svg></div>`;
  return{html,lanes,geometry,boardWidth};
}
